`,
}

export async function generateEvalTask({
  client,
  input,
  agentDefinitions,
}: {
  client: SavantCodeClient
  input: {
    commitSha: string
    parentSha: string
    diff: string
    editedFilePaths: string[]
    commitMessage?: string
    repoPath: string
  }
  agentDefinitions?: any[]
}): Promise<{
  id: string
  reasoning: string
  spec: string
  prompt: string
  supplementalFiles: string[]
}> {
  const { diff, editedFilePaths, commitMessage, repoPath } = input

  const allAgentDefinitions = [
    evalTaskGeneratorAgentDef,
    ...(agentDefinitions || []),
  ]

  const generatorResult = await client.run({
    agent: 'eval-task-generator',
    prompt:
      'Generate a task specification and user prompt based on the git diff and codebase exploration',
    params: {
      diff,
      editedFilePaths,
      ...(commitMessage !== undefined ? { commitMessage } : {}),
    },
    cwd: repoPath,
    agentDefinitions: allAgentDefinitions,
    handleEvent: (event) => {
      if (event.type === 'subagent_start') {
        console.log(`[Agent] Starting: ${event.displayName}`)
      } else if (event.type === 'tool_call') {
        console.log(`[Tool] ${event.toolName}`)
      } else if (event.type === 'text') {
        console.log(`[Text] ${event.text}...`)
      }
    },
  })

  if (
    generatorResult.output.type !== 'structuredOutput' ||
    !generatorResult.output.value
  ) {
    throw new Error('Failed to generate structured task output')
  }

  return generatorResult.output.value as {
    id: string
    reasoning: string
    spec: string
    prompt: string
    supplementalFiles: string[]
  }
}

import { cp } from 'node:fs/promises'
import path from 'node:path'

import pLimit from 'p-limit'

import { MetricAggregator, type MetricReport } from './metrics'
import { loadTaskRegistry } from './registry'
import { DeterministicVerifier, type VerificationResult } from './verify'

import type { AgentRunner, TraceDocument } from './runner'
import type { Sandbox } from './sandbox'
import type {
  TaskCategory,
  TaskDefinition,
  TaskDifficulty,
  TaskRegistry,
} from './schema'


export type HarnessMode = 'evaluate' | 'baseline'

export interface HarnessOptions {
  /**
   * Directory containing task definition files. Either `tasksDir` or `tasks`
   * must be provided.
   */
  tasksDir?: string
  /**
   * Inline task registry. Useful for testing or for callers that already have
   * the registry in memory. Either `tasksDir` or `tasks` must be provided.
   */
  tasks?: TaskDefinition[]
  /**
   * Factory that creates a fresh sandbox for a given task.
   * The harness calls prepare() before the run and teardown() afterwards.
   */
  sandboxFactory: (task: TaskDefinition) => Sandbox
  /**
   * Factory that creates and fully initializes a runner for a task in
   * evaluate mode. Not used in baseline mode.
   */
  agentRunnerFactory?: (
    task: TaskDefinition,
    sandbox: Sandbox,
  ) => Promise<AgentRunner>
  /** Run mode. */
  mode?: HarnessMode
  /**
   * Optional global timeout for the whole harness run.
   * When the timeout fires, the harness stops accepting new tasks; any tasks
   * already in progress continue until they complete or hit their own
   * `timeout_seconds`.
   * Individual tasks still honor their own timeout.
   */
  globalTimeoutMs?: number
  /** Maximum number of tasks to run concurrently. */
  concurrency?: number
  /** Only run tasks whose category matches this value. */
  category?: TaskCategory
  /** Only run tasks whose difficulty matches this value. */
  difficulty?: TaskDifficulty
}

export interface TaskResult {
  task_id: string
  task: TaskDefinition
  status: 'PASS' | 'FAIL' | 'TIMEOUT' | 'ERROR'
  trace?: TraceDocument
  metrics?: MetricReport
  verification?: VerificationResult
  error?: string
}

export interface HarnessResult {
  results: TaskResult[]
  total: number
  passed: number
  failed: number
  errors: number
  timeouts: number
  duration_ms: number
}

class TaskTimeoutError extends Error {
  constructor(taskId: string, timeoutMs: number) {
    super(`Task ${taskId} timeout after ${timeoutMs}ms`)
    this.name = 'TaskTimeoutError'
  }
}

/**
 * Orchestrates benchmark runs across a registry of tasks.
 *
 * - In `evaluate` mode, the harness runs the configured agent against each task,
 *   then runs deterministic verification and metric aggregation.
 * - In `baseline` mode, the harness skips the agent run and applies the task's
 *   golden patch before verification, letting task authors validate their tasks.
 */
export class BenchmarkHarness {
  constructor(private readonly options: HarnessOptions) {}

  async run(): Promise<HarnessResult> {
    let tasks: TaskDefinition[]

    if (this.options.tasks) {
      tasks = this.options.tasks
    } else if (this.options.tasksDir) {
      const registry = await loadTaskRegistry(this.options.tasksDir)
      tasks = Object.values(registry)
      if (this.options.category) {
        tasks = tasks.filter((task) => task.category === this.options.category)
      }
      if (this.options.difficulty) {
        tasks = tasks.filter(
          (task) => task.difficulty === this.options.difficulty,
        )
      }
    } else {
      throw new Error('Either tasksDir or tasks must be provided')
    }

    const limit = pLimit(Math.max(1, this.options.concurrency ?? 1))
    const startedAt = Date.now()

    let globalTimer: ReturnType<typeof setTimeout> | undefined
    let aborted = false

    if (this.options.globalTimeoutMs && this.options.globalTimeoutMs > 0) {
      globalTimer = setTimeout(() => {
        aborted = true
      }, this.options.globalTimeoutMs)
    }

    const runPromises = tasks.map((task) =>
      limit(async () => {
        if (aborted) {
          return this.timeoutResult(task, 'Global harness timeout exceeded')
        }

        try {
          return await this.withTaskTimeout(task, this.runTask(task))
        } catch (error) {
          if (error instanceof TaskTimeoutError) {
            return this.timeoutResult(task, error.message)
          }
          return this.errorResult(task, error)
        }
      }),
    )

    const results = await Promise.all(runPromises)

    if (globalTimer) clearTimeout(globalTimer)

    const durationMs = Date.now() - startedAt
    const passed = results.filter((r) => r.status === 'PASS').length
    const failed = results.filter((r) => r.status === 'FAIL').length
    const errors = results.filter((r) => r.status === 'ERROR').length
    const timeouts = results.filter((r) => r.status === 'TIMEOUT').length

    return {
      results,
      total: tasks.length,
      passed,
      failed,
      errors,
      timeouts,
      duration_ms: durationMs,
    }
  }

  private async runTask(task: TaskDefinition): Promise<TaskResult> {
    const sandbox = this.options.sandboxFactory(task)

    try {
      await sandbox.prepare()

      // Copy task files into the sandbox before running the setup script.
      if (
        task.environment.setup_files &&
        task.environment.setup_files.length > 0
      ) {
        if (!task.task_dir) {
          throw new Error(
            `task ${task.task_id} has setup_files but no task_dir; load the task through the registry so the task directory is known`,
          )
        }
        for (const file of task.environment.setup_files) {
          const taskDir = path.resolve(task.task_dir)
          const src = path.resolve(taskDir, file)
          // Defensive: reject paths that escape the task directory.
          const relative = path.relative(taskDir, src)
          if (relative.startsWith('..') || path.isAbsolute(relative)) {
            throw new Error(`setup_files entry escapes task directory: ${file}`)
          }
          const dest = path.resolve(sandbox.getWorkingDir(), file)
          await cp(src, dest, { recursive: true })
        }
      }

      // Run the task's environment setup script (install deps, seed files, etc.).
      if (task.environment.setup_script) {
        const setupResult = await sandbox.runCommand(
          task.environment.setup_script,
          { shell: true },
        )
        if (setupResult.exitCode !== 0) {
          const details = [
            `exitCode=${setupResult.exitCode}`,
            setupResult.stdout ? `stdout=${setupResult.stdout}` : undefined,
            setupResult.stderr ? `stderr=${setupResult.stderr}` : undefined,
          ]
            .filter(Boolean)
            .join(' ')
          throw new Error(`Setup script failed: ${details}`)
        }
      }

      const mode = this.options.mode ?? 'evaluate'
      let trace: TraceDocument | undefined

      if (mode === 'evaluate') {
        if (!this.options.agentRunnerFactory) {
          throw new Error('agentRunnerFactory is required in evaluate mode')
        }
        const runner = await this.options.agentRunnerFactory(task, sandbox)
        await runner.executePrompt(task.inputs.prompt)
        trace = runner.collectTrace()
      }

      const verifier = new DeterministicVerifier(sandbox, {
        applyGoldenPatch: mode === 'baseline',
      })

      const verification = await verifier.verify(task)

      const metrics = trace
        ? MetricAggregator.aggregate(trace, task)
        : undefined
      const passed = verification.passed && (metrics ? metrics.passed : true)

      return {
        task_id: task.task_id,
        task,
        status: passed ? 'PASS' : 'FAIL',
        trace,
        metrics,
        verification,
      }
    } finally {
      await sandbox.teardown()
    }
  }

  private async withTaskTimeout<T>(
    task: TaskDefinition,
    promise: Promise<T>,
  ): Promise<T> {
    const timeoutMs = (task.validation.timeout_seconds ?? 300) * 1000
    if (!Number.isFinite(timeoutMs) || timeoutMs <= 0) {
      return promise
    }

    return new Promise<T>((resolve, reject) => {
      const timer = setTimeout(() => {
        reject(new TaskTimeoutError(task.task_id, timeoutMs))
      }, timeoutMs)

      promise
        .then((value) => {
          clearTimeout(timer)
          resolve(value)
        })
        .catch((error) => {
          clearTimeout(timer)
          reject(error)
        })
    })
  }

  private timeoutResult(task: TaskDefinition, message: string): TaskResult {
    return {
      task_id: task.task_id,
      task,
      status: 'TIMEOUT',
      error: message,
    }
  }

  private errorResult(task: TaskDefinition, error: unknown): TaskResult {
    const message = error instanceof Error ? error.message : String(error)
    return {
      task_id: task.task_id,
      task,
      status: 'ERROR',
      error: message,
    }
  }
}

import { readdir, readFile } from 'node:fs/promises'
import path from 'node:path'

import { parse as parseYaml } from 'yaml'
import { z } from 'zod'

import {
  taskDefinitionSchema,
  taskRegistrySchema,
  type TaskDefinition,
  type TaskRegistry,
} from './schema'

export interface RegistryLoadOptions {
  recursive?: boolean
  extensions?: string[]
}

const DEFAULT_EXTENSIONS = ['.json', '.yaml', '.yml']

export class TaskRegistryError extends Error {
  constructor(
    message: string,
    public readonly cause?: unknown,
  ) {
    super(message)
    this.name = 'TaskRegistryError'
  }
}

function parseTaskFile(content: string, filePath: string): unknown {
  const ext = path.extname(filePath).toLowerCase()
  if (ext === '.json') {
    try {
      return JSON.parse(content)
    } catch (err) {
      throw new TaskRegistryError(
        `Invalid JSON in task file ${filePath}: ${err instanceof Error ? err.message : String(err)}`,
        err,
      )
    }
  }
  if (ext === '.yaml' || ext === '.yml') {
    try {
      return parseYaml(content)
    } catch (err) {
      throw new TaskRegistryError(
        `Invalid YAML in task file ${filePath}: ${err instanceof Error ? err.message : String(err)}`,
        err,
      )
    }
  }
  throw new TaskRegistryError(`Unsupported task file extension: ${filePath}`)
}

function validateTaskDefinition(
  data: unknown,
  filePath: string,
): TaskDefinition {
  const result = taskDefinitionSchema.safeParse(data)
  if (!result.success) {
    const issues = result.error.issues
      .map((issue) => `${issue.path.join('.')}: ${issue.message}`)
      .join('; ')
    throw new TaskRegistryError(
      `Task validation failed for ${filePath}: ${issues}`,
      result.error,
    )
  }
  return result.data
}

export async function loadTaskFromFile(
  filePath: string,
): Promise<TaskDefinition> {
  const content = await readFile(filePath, 'utf-8')
  const data = parseTaskFile(content, filePath)
  const task = validateTaskDefinition(data, filePath)
  return resolvePaths(task, filePath)
}

function resolvePaths(task: TaskDefinition, filePath: string): TaskDefinition {
  const taskDir = path.dirname(filePath)
  let goldenPatch = task.golden_patch
  if (goldenPatch && !path.isAbsolute(goldenPatch)) {
    goldenPatch = path.resolve(taskDir, goldenPatch)
  }
  return {
    ...task,
    golden_patch: goldenPatch,
    task_dir: taskDir,
  }
}

export async function loadTaskRegistry(
  tasksDir: string,
  options: RegistryLoadOptions = {},
): Promise<TaskRegistry> {
  const { recursive = true, extensions = DEFAULT_EXTENSIONS } = options
  const registry: TaskRegistry = {}
  const firstSeenPaths = new Map<string, string>()

  async function scan(dir: string): Promise<void> {
    let entries
    try {
      entries = await readdir(dir, { withFileTypes: true })
    } catch (err) {
      throw new TaskRegistryError(
        `Failed to read tasks directory ${dir}: ${err instanceof Error ? err.message : String(err)}`,
        err,
      )
    }

    for (const entry of entries) {
      const fullPath = path.join(dir, entry.name)
      if (entry.isDirectory() && recursive) {
        await scan(fullPath)
        continue
      }
      if (!entry.isFile()) continue

      const ext = path.extname(entry.name).toLowerCase()
      if (!extensions.includes(ext)) continue

      const task = await loadTaskFromFile(fullPath)
      if (task.task_id in registry) {
        throw new TaskRegistryError(
          `Duplicate task_id "${task.task_id}" in ${fullPath} (first seen in ${firstSeenPaths.get(task.task_id) ?? 'unknown'})`,
        )
      }
      registry[task.task_id] = task
      firstSeenPaths.set(task.task_id, fullPath)
    }
  }

  await scan(tasksDir)

  // Sort the registry by task_id so that consumers (reports, harness loops,
  // leaderboard generation) always see tasks in a deterministic order rather
  // than filesystem order.
  const sortedRegistry: TaskRegistry = {}
  const sortedKeys = Object.keys(registry).sort((a, b) =>
    a.localeCompare(b, 'en'),
  )
  for (const key of sortedKeys) {
    sortedRegistry[key] = registry[key]
  }

  return sortedRegistry
}

export function loadTaskRegistryFromObject(data: unknown): TaskRegistry {
  const result = taskRegistrySchema.safeParse(data)
  if (!result.success) {
    const issues = result.error.issues
      .map((issue) => `${issue.path.join('.')}: ${issue.message}`)
      .join('; ')
    throw new TaskRegistryError(
      `Task registry validation failed: ${issues}`,
      result.error,
    )
  }
  return result.data
}

export function filterTasksByCategory(
  registry: TaskRegistry,
  category: TaskDefinition['category'],
): TaskDefinition[] {
  return Object.values(registry).filter((task) => task.category === category)
}

export function filterTasksByDifficulty(
  registry: TaskRegistry,
  difficulty: TaskDefinition['difficulty'],
): TaskDefinition[] {
  return Object.values(registry).filter(
    (task) => task.difficulty === difficulty,
  )
}

import { writeFile } from 'node:fs/promises'

import type { HarnessResult, TaskResult } from './harness'

/**
 * Write the raw harness result as JSON.
 */
export async function writeJsonReport(
  result: HarnessResult,
  filePath: string,
): Promise<void> {
  const json = JSON.stringify(result, null, 2)
  await writeFile(filePath, json, 'utf-8')
}

/**
 * Write a human-readable Markdown summary of the harness run.
 */
export async function writeMarkdownReport(
  result: HarnessResult,
  filePath: string,
): Promise<void> {
  const lines: string[] = []

  lines.push('# Savant-Code Benchmark v2 Results')
  lines.push('')
  lines.push(`**Total:** ${result.total}`)
  lines.push(`**Passed:** ${result.passed}`)
  lines.push(`**Failed:** ${result.failed}`)
  lines.push(`**Errors:** ${result.errors}`)
  lines.push(`**Timeouts:** ${result.timeouts}`)
  lines.push(`**Duration:** ${(result.duration_ms / 1000).toFixed(2)}s`)
  lines.push('')

  lines.push(
    '| Task ID | Category | Difficulty | Status | Verification | Metrics | Duration | Cost |',
  )
  lines.push(
    '|---------|----------|------------|--------|--------------|---------|----------|------|',
  )

  for (const r of result.results) {
    const verification = r.verification?.status ?? '-'
    const metrics = r.metrics ? (r.metrics.passed ? 'Yes' : 'No') : '-'
    const duration = r.trace?.metadata.duration_ms
      ? `${(r.trace.metadata.duration_ms / 1000).toFixed(1)}s`
      : '-'
    const cost =
      r.trace?.metadata.cost_usd !== undefined
        ? `$${r.trace.metadata.cost_usd.toFixed(4)}`
        : '-'

    lines.push(
      `| ${r.task_id} | ${r.task.category} | ${r.task.difficulty} | ${r.status} | ${verification} | ${metrics} | ${duration} | ${cost} |`,
    )
  }

  lines.push('')

  const failures = result.results.filter((r) => r.status !== 'PASS')
  if (failures.length > 0) {
    lines.push('## Failures')
    lines.push('')
    for (const r of failures) {
      lines.push(`### ${r.task_id}`)
      lines.push(`- **Status:** ${r.status}`)
      if (r.error) lines.push(`- **Error:** ${r.error}`)
      if (r.verification) {
        lines.push(`- **Verification:** ${r.verification.status}`)
      }
      if (r.metrics && !r.metrics.passed) {
        lines.push(`- **Metrics passed:** ${r.metrics.passed}`)
        if (r.metrics.fsm.invalid_transitions > 0) {
          lines.push(
            `  - Invalid FSM transitions: ${r.metrics.fsm.invalid_transitions}`,
          )
        }
        if (r.metrics.fsm.write_in_red_violations > 0) {
          lines.push(
            `  - Write outside allowed phase: ${r.metrics.fsm.write_in_red_violations}`,
          )
        }
        if (!r.metrics.subagent.utilization_passed) {
          lines.push(`  - Subagent utilization failed`)
        }
      }
      lines.push('')
    }
  }

  await writeFile(filePath, lines.join('\n'), 'utf-8')
}

import { spawn } from 'node:child_process'
import { mkdtemp, rm } from 'node:fs/promises'
import { tmpdir } from 'node:os'
import path from 'node:path'

import type { Sandbox, CommandOptions, CommandResult } from '../sandbox'

export interface TempDirSandboxOptions {
  /** Optional prefix for the temp directory name. */
  prefix?: string
  /** If true, preserve the directory after teardown (useful for debugging). */
  preserve?: boolean
}

/**
 * Lightweight sandbox that creates a temporary directory on the local
 * filesystem. This is the default on Windows; on Linux/macOS/CI it can be
 * swapped for the Docker sandbox.
 */
export class TempDirSandbox implements Sandbox {
  public readonly id: string
  private workingDir: string = ''
  private readonly prefix: string
  private readonly preserve: boolean

  constructor(options: TempDirSandboxOptions = {}) {
    this.id = `tempdir-${crypto.randomUUID()}`
    this.prefix = options.prefix ?? 'savant-bench-'
    this.preserve = options.preserve ?? false
  }

  async prepare(): Promise<void> {
    this.workingDir = await mkdtemp(path.join(tmpdir(), this.prefix))
  }

  getWorkingDir(): string {
    if (!this.workingDir) {
      throw new Error('Sandbox has not been prepared. Call prepare() first.')
    }
    return this.workingDir
  }

  async runCommand(
    command: string,
    options: Partial<CommandOptions> = {},
  ): Promise<CommandResult> {
    const cwd = this.getWorkingDir()
    const resolvedCwd = options.cwd ? path.join(cwd, options.cwd) : cwd

    const isWindows = process.platform === 'win32'
    const child = spawn(command, [], {
      cwd: resolvedCwd,
      shell: options.shell ?? true,
      env: this.buildEnv(options.env),
      stdio: ['ignore', 'pipe', 'pipe'],
    })

    return new Promise((resolve, reject) => {
      let stdout = ''
      let stderr = ''
      let killed = false
      const timeout = options.timeout

      child.stdout?.on('data', (data: Buffer) => {
        stdout += data.toString()
      })
      child.stderr?.on('data', (data: Buffer) => {
        stderr += data.toString()
      })

      const timeoutId =
        timeout && timeout > 0
          ? setTimeout(() => {
              killed = true
              // Best-effort termination. On Windows this only kills the shell
              // process; a future Docker/Firecracker sandbox should be used for
              // stronger isolation.
              try {
                child.kill()
              } catch {
                // Process may have already exited naturally.
              }
            }, timeout)
          : undefined

      child.on('error', (error) => {
        if (timeoutId) clearTimeout(timeoutId)
        reject(error)
      })

      child.on('close', (exitCode) => {
        if (timeoutId) clearTimeout(timeoutId)
        resolve({
          exitCode: exitCode ?? (killed ? 124 : 1),
          stdout,
          stderr,
          timedOut: killed,
        })
      })
    })
  }

  async teardown(): Promise<void> {
    if (!this.workingDir || this.preserve) {
      return
    }
    await rm(this.workingDir, { recursive: true, force: true })
    this.workingDir = ''
  }

  private buildEnv(
    overrides: Record<string, string> | undefined,
  ): NodeJS.ProcessEnv {
    // MVP: inherit the host environment. This leaks host env variables, but it
    // keeps temp-dir sandbox simple. Use Docker/Firecracker for real isolation.
    return {
      ...process.env,
      ...(overrides ?? {}),
    }
  }
}

import { describe, it, expect, beforeEach } from 'bun:test'

import { BenchmarkHarness, type HarnessOptions } from '../src/harness'

import type { AgentRunner, TraceDocument } from '../src/runner'
